package coralnpu

import chisel3._
import chisel3.util._

/** Multiply unit operation encoding. */
object MluOp extends ChiselEnum {
  val MUL  = Value  // 32x32 → 32 low multiply
  val MULH = Value  // signed×signed → high 32 bits
  val MULHU = Value // unsigned×unsigned → high 32 bits
  val MULHSU = Value // signed×unsigned → high 32 bits
}

/** Request bundle for one multiply lane. */
class MluRequest extends Bundle {
  val addr = UInt(5.W)   // destination register address
  val op   = MluOp()
}

/** Result bundle from the multiply unit. */
class MluResult extends Bundle {
  val addr = UInt(5.W)
  val data = UInt(32.W)
}

/** Multiply operand with validity. */
class MluOperand extends Bundle {
  val valid = Bool()
  val data  = UInt(32.W)
}

/** 4-wide pipelined multiply unit.
  *
  * Each of the four lanes can accept an independent multiply request.
  * Results are drained one at a time through the single Decoupled `rd` port.
  * Timing: a result is available one clock after the request is presented
  * (registered multiply), and is held until `rd.ready` is asserted.
  *
  * Only the first valid lane's result is queued in this implementation; the
  * remaining lanes are available for future extension.
  */
class Mlu(p: Parameters) extends Module {
  val numLanes = 4

  val io = IO(new Bundle {
    val req = Input(Vec(numLanes, Valid(new MluRequest)))
    val rs1 = Input(Vec(numLanes, new MluOperand))
    val rs2 = Input(Vec(numLanes, new MluOperand))
    val rd  = Decoupled(new MluResult)
  })

  // -----------------------------------------------------------------------
  // Per-lane combinational multiply
  // -----------------------------------------------------------------------
  val laneResult = Wire(Vec(numLanes, UInt(32.W)))
  for (i <- 0 until numLanes) {
    val a = io.rs1(i).data
    val b = io.rs2(i).data
    laneResult(i) := MuxLookup(io.req(i).bits.op, (a * b)(31, 0))(Seq(
      MluOp.MUL    -> (a * b)(31, 0),
      MluOp.MULH   -> (a.asSInt * b.asSInt).asUInt(63, 32),
      MluOp.MULHU  -> (a * b)(63, 32),
      MluOp.MULHSU -> (a.asSInt * b.asUInt).asUInt(63, 32),
    ))
  }

  // -----------------------------------------------------------------------
  // Simple single-entry output queue.
  //
  // We grab the first active lane and register its result.
  // The result stays valid until rd.ready is asserted.
  // -----------------------------------------------------------------------
  val pendingValid = RegInit(false.B)
  val pendingAddr  = Reg(UInt(5.W))
  val pendingData  = Reg(UInt(32.W))

  // Find the first valid lane
  val anyValid = io.req.map(_.valid).reduce(_ || _)
  val firstLane = PriorityEncoder(VecInit(io.req.map(_.valid)))

  // Capture on the rising edge when nothing is pending (or being consumed)
  val capture = anyValid && (!pendingValid || io.rd.ready)

  when(io.rd.ready && pendingValid) {
    pendingValid := false.B
  }
  when(capture) {
    pendingValid := true.B
    pendingAddr  := io.req(firstLane).bits.addr
    pendingData  := laneResult(firstLane)
  }

  io.rd.valid      := pendingValid
  io.rd.bits.addr  := pendingAddr
  io.rd.bits.data  := pendingData
}

/** Emit helper used by the build system. */
object EmitMlu extends App {
  import circt.stage.ChiselStage
  ChiselStage.emitSystemVerilog(new Mlu(new Parameters), args)
}

