package coralnpu

import chisel3._
import chisel3.util._

import common.{Fp32, Fma, FmaCmd}

/** FPU operation type. */
object FpuOptype extends ChiselEnum {
  val FpuAdd = Value  // result = ina + inc
  val FpuSub = Value  // result = ina - inc
  val FpuMul = Value  // result = ina * inb
}

/** Command bundle for the FPU. */
class FpuCmd extends Bundle {
  val optype = FpuOptype()
  val waddr  = UInt(5.W)   // writeback register address
  val ina    = new Fp32
  val inb    = new Fp32
  val inc    = new Fp32
}

/** Output bundle from the FPU. */
class FpuOutput extends Bundle {
  val addr = UInt(5.W)
  val bits = new Fp32
}

/** Single-cycle FPU (FpuAdd, FpuSub, FpuMul).
  *
  * Operations:
  *   FpuAdd : ina + inc  (mapped to FMA: ina * 1.0 + inc)
  *   FpuSub : ina - inc  (mapped to FMA: ina * 1.0 + (-inc))
  *   FpuMul : ina * inb  (mapped to FMA: ina * inb + 0.0)
  *
  * Pipeline: 1-cycle latency (result registered, visible the cycle after cmd).
  * Output is Decoupled; if ready=0 the result is held until consumed.
  */
class Fpu extends Module {
  val io = IO(new Bundle {
    val cmd    = Flipped(Valid(new FpuCmd))
    val output = Decoupled(new FpuOutput)
  })

  // -----------------------------------------------------------------------
  // Constant Fp32 values used for operation mapping
  // -----------------------------------------------------------------------
  val fp_one = Wire(new Fp32)
  fp_one.sign     := false.B
  fp_one.exponent := 127.U   // biased exponent for 1.0
  fp_one.mantissa := 0.U

  val fp_zero = Wire(new Fp32)
  fp_zero.sign     := false.B
  fp_zero.exponent := 0.U
  fp_zero.mantissa := 0.U

  // -----------------------------------------------------------------------
  // Map operation to FMA inputs (ina * inb + inc)
  // -----------------------------------------------------------------------
  val fmaCmd = Wire(new FmaCmd)

  fmaCmd.ina := io.cmd.bits.ina
  fmaCmd.inb := DontCare
  fmaCmd.inc := DontCare

  switch(io.cmd.bits.optype) {
    is(FpuOptype.FpuAdd) {
      // ina + inc = ina * 1.0 + inc
      fmaCmd.inb := fp_one
      fmaCmd.inc := io.cmd.bits.inc
    }
    is(FpuOptype.FpuSub) {
      // ina - inc = ina * 1.0 + (-inc)
      val negInc = Wire(new Fp32)
      negInc.sign     := !io.cmd.bits.inc.sign
      negInc.exponent := io.cmd.bits.inc.exponent
      negInc.mantissa := io.cmd.bits.inc.mantissa
      fmaCmd.inb := fp_one
      fmaCmd.inc := negInc
    }
    is(FpuOptype.FpuMul) {
      // ina * inb + 0
      fmaCmd.inb := io.cmd.bits.inb
      fmaCmd.inc := fp_zero
    }
  }

  // -----------------------------------------------------------------------
  // FMA pipeline (3 combinational stages)
  // -----------------------------------------------------------------------
  val fmaS1     = Fma.FmaStage1(fmaCmd)
  val fmaS2     = Fma.FmaStage2(fmaS1)
  val fmaResult = Fma.FmaStage3(fmaS2)

  // -----------------------------------------------------------------------
  // Output pipeline register (1-cycle latency)
  // -----------------------------------------------------------------------
  val outValid = RegInit(false.B)
  val outAddr  = Reg(UInt(5.W))
  val outBits  = Reg(new Fp32)

  // Advance when output is free (not valid, or being consumed this cycle)
  val outFree = !outValid || io.output.ready

  when(outFree) {
    outValid := io.cmd.valid
    when(io.cmd.valid) {
      outAddr := io.cmd.bits.waddr
      outBits := fmaResult
    }
  }

  io.output.valid      := outValid
  io.output.bits.addr  := outAddr
  io.output.bits.bits  := outBits
}

