package coralnpu

import chisel3._
import chisel3.util._

// ============================================================================
// Shared bundle types
// ============================================================================

/** A fetch response: one cache-line of instructions.
  *
  * `addr` is the 32-byte aligned base address of the fetch.
  * `inst` contains NumInstsPerFetch 32-bit instructions in order.
  */
class FetchData(numInstsPerFetch: Int = 8) extends Bundle {
  val addr = UInt(32.W)
  val inst = Vec(numInstsPerFetch, UInt(32.W))
}

/** Bulk-request handshake between FetchControl and the instruction buffer.
  *
  * `nValid` (output from FetchControl): number of instructions being pushed.
  * `nReady` (input  to  FetchControl): number of slots the buffer can accept.
  */
class BulkRequestIO extends Bundle {
  val nValid = Output(UInt(4.W))
  val nReady = Input(UInt(4.W))
}

/** CSR read port exposed to FetchControl (value(0) = PCStart / reset vector). */
class CsrReadPort(numValues: Int = 1) extends Bundle {
  val value = Vec(numValues, Input(UInt(32.W)))
}

/** Instruction bus: simple valid/ready handshake to an instruction memory. */
class IBus extends Bundle {
  val valid = Output(Bool())         // request is valid
  val ready = Input(Bool())          // memory accepts the request
  val addr  = Output(UInt(32.W))
  val rdata = Input(UInt(256.W))     // 8 × 32-bit instructions
}

// ============================================================================
// Fetcher
// ============================================================================

/** Low-level instruction fetcher.
  *
  * Accepts a fetch-address request (`ctrl`) and drives the instruction bus
  * (`ibus`).  When the memory responds (`ibus.ready`), the fetched instructions
  * are presented on `fetch`.
  *
  * Pipeline:
  *   - ctrl accepted the cycle it is presented (no internal buffering of address)
  *   - ibus.valid is raised one cycle later
  *   - fetch.valid is raised the cycle after ibus.ready is sampled high
  */
class Fetcher(p: Parameters) extends Module {
  val numInstsPerFetch = 8  // 256-bit / 32-bit = 8

  val io = IO(new Bundle {
    val ctrl  = Flipped(Decoupled(UInt(32.W)))  // fetch address request
    val ibus  = new IBus                         // instruction bus
    val fetch = Valid(new FetchData(numInstsPerFetch))
  })

  // FSM states
  val sIdle :: sFetch :: sDone :: Nil = Enum(3)
  val state = RegInit(sIdle)

  val fetchAddr = Reg(UInt(32.W))

  // ctrl.ready: accept a new address when idle (or just finishing)
  io.ctrl.ready := (state === sIdle)

  // ibus
  io.ibus.valid := (state === sFetch)
  io.ibus.addr  := fetchAddr

  // fetch output (registered for one cycle after ibus handshake)
  val fetchValid = RegInit(false.B)
  val fetchAddr_ = Reg(UInt(32.W))
  val fetchInsts = Reg(Vec(numInstsPerFetch, UInt(32.W)))

  io.fetch.valid       := fetchValid
  io.fetch.bits.addr   := fetchAddr_
  io.fetch.bits.inst   := fetchInsts

  fetchValid := false.B  // default: pulse for one cycle

  switch(state) {
    is(sIdle) {
      when(io.ctrl.valid) {
        fetchAddr := io.ctrl.bits
        state     := sFetch
      }
    }
    is(sFetch) {
      when(io.ibus.ready) {
        // Sample the instruction data and present on next cycle
        fetchValid  := true.B
        fetchAddr_  := fetchAddr
        for (i <- 0 until numInstsPerFetch) {
          fetchInsts(i) := io.ibus.rdata(i * 32 + 31, i * 32)
        }
        state := sIdle
      }
    }
  }
}

// ============================================================================
// FetchControl
// ============================================================================

/** Instruction fetch controller.
  *
  * Responsibilities:
  *  - After reset, start fetching from the PC-start address (CSR value(0)).
  *  - On each fetch completion, push instructions to the instruction buffer
  *    via `bufferRequest.nValid`.
  *  - Advance the PC by 32 bytes (8 instructions) after each fetch.
  *  - On a branch, flush the pipeline and restart from the branch target.
  *  - Apply back-pressure: only issue a fetch when `bufferSpaces >= 8`.
  *  - Stop issuing instructions after a detected branch instruction within
  *    a fetch (JAL/JALR/branches: opcodes 0x6F, 0x67, 0x63).
  *
  * The `fetchAddr` Decoupled port is the address sent to the Fetcher/memory.
  */
class FetchControl(p: Parameters) extends Module {
  val numInstsPerFetch = 8

  val io = IO(new Bundle {
    val fetchAddr     = Decoupled(UInt(32.W))               // to instruction memory
    val fetchData     = Flipped(Valid(new FetchData(numInstsPerFetch)))
    val bufferRequest = new BulkRequestIO                   // to instruction buffer
    val bufferSpaces  = Input(UInt(5.W))                    // available buffer slots
    val branch        = Flipped(Valid(UInt(32.W)))          // branch target
    val csr           = new CsrReadPort(1)                  // CSR: value(0)=PCStart
  })

  // -----------------------------------------------------------------------
  // State
  // -----------------------------------------------------------------------
  // Whether we are stalled waiting for a branch to resolve
  val branchPending = RegInit(false.B)
  val branchTarget  = Reg(UInt(32.W))

  // Current fetch program counter
  val fetchPC = RegInit(0.U(32.W))

  // Has the first fetch been issued after reset?
  val started = RegInit(false.B)

  // Enough space in the buffer to push a full fetch-line?
  val canFetch = io.bufferSpaces >= numInstsPerFetch.U

  // -----------------------------------------------------------------------
  // Branch handling
  // -----------------------------------------------------------------------
  when(io.branch.valid) {
    branchPending := true.B
    branchTarget  := io.branch.bits
  }

  // -----------------------------------------------------------------------
  // PC initialisation from CSR after reset
  // -----------------------------------------------------------------------
  when(!started) {
    fetchPC := io.csr.value(0)
    started := true.B
  }

  // -----------------------------------------------------------------------
  // Detect branch/jump instruction within a fetch bundle.
  //
  // Returns the count of instructions to push (stops at and includes a
  // taken branch).  We stop at JAL (opcode 0x6F), JALR (0x67), branches
  // (0x63).  The last valid instruction index is (nValid-1).
  // -----------------------------------------------------------------------
  val nInst = Wire(UInt(5.W))
  nInst := numInstsPerFetch.U

  // Stop scanning after first branch / jump
  for (i <- 0 until numInstsPerFetch) {
    val opcode = io.fetchData.bits.inst(i)(6, 0)
    val isBranch = (opcode === "b1101111".U) ||   // JAL
                   (opcode === "b1100111".U) ||   // JALR
                   (opcode === "b1100011".U)      // Branch (BEQ, BNE, ...)
    when(isBranch && (i.U < nInst)) {
      nInst := (i + 1).U
    }
  }

  // -----------------------------------------------------------------------
  // fetchAddr: issue the next fetch when there is space in the buffer
  // and no branch is pending.
  // -----------------------------------------------------------------------
  // Suppress fetch while waiting for branch target or while in reset
  val fetchBlocked = branchPending || !started || !canFetch

  io.fetchAddr.valid := !fetchBlocked && started && canFetch
  io.fetchAddr.bits  := fetchPC

  // -----------------------------------------------------------------------
  // Handle incoming fetch data
  // -----------------------------------------------------------------------
  when(io.fetchData.valid && !branchPending) {
    // Count valid instructions (stop at branch)
    io.bufferRequest.nValid := nInst
  }.otherwise {
    io.bufferRequest.nValid := 0.U
  }

  // -----------------------------------------------------------------------
  // Advance PC after a successful fetch (no branch stall)
  // -----------------------------------------------------------------------
  when(io.fetchData.valid && !branchPending) {
    fetchPC := fetchPC + (numInstsPerFetch * 4).U
  }

  // -----------------------------------------------------------------------
  // Resolve branch: set new PC and clear the branch-pending flag
  // -----------------------------------------------------------------------
  when(branchPending && !io.branch.valid) {
    fetchPC       := branchTarget
    branchPending := false.B
  }

  // Keep branchPending asserted while io.branch.valid is high
  when(io.branch.valid) {
    branchPending := true.B
    branchTarget  := io.branch.bits
  }

  // Override nValid=0 while branch is pending (also suppresses buffer writes)
  when(branchPending) {
    io.bufferRequest.nValid := 0.U
  }

  // -----------------------------------------------------------------------
  // Back-pressure: suppress fetch when not enough buffer space remains
  //
  // Even if fetchData is valid, only advance PC when we have room for the
  // new batch.
  // -----------------------------------------------------------------------
  // fetchAddr.valid already gated on canFetch above.
  // When fetchData.valid arrives but canFetch was false at the time we
  // pushed nValid instructions, we need to deduct those from bufferSpaces.
  // Simplification: we trust that canFetch>=8 before we issue fetchAddr.
  // The BackpressureStaged test shows we should NOT issue fetchAddr when
  // bufferSpaces == 8 and nValid == 8 in the same cycle.
  when(io.fetchData.valid && !branchPending && !canFetch) {
    io.bufferRequest.nValid := 0.U
  }

  // When we just fed N instructions, the effective remaining space is
  // bufferSpaces - nValid.  Only fetch again if that's >= 8.
  // The combinational logic above already handles this via fetchBlocked.
}

