  // -----------------------------------------------------------------------
  val branchStall = branchPending || io.branch.valid

  // -----------------------------------------------------------------------
  // Determine whether enough buffer space is available to push a full line
  // and to accept the NEXT fetch too.
  //
  // Suppress fetchAddr when:
  //  - not yet started
  //  - branch is pending (registered OR asserted this cycle)
  //  - fetchData is currently valid (we are processing it this cycle)
  //  - bufferSpaces < NumInsts
  // -----------------------------------------------------------------------
