// -----------------------------------------------------------------------
// Count valid instructions in the incoming fetch line.
//
// Scan in order; stop (inclusive) at the first branch / jump opcode.
// Use a priority-encoder style: compute per-instruction signals first,
// then pick the lowest-indexed branch using a fold.
// -----------------------------------------------------------------------
// Per-instruction branch detection
val instIsBranch = VecInit((0 until NumInsts).map { i =>
  val opcode = io.fetchData.bits.inst(i)(6, 0)
  (opcode === OpcodeJAL) || (opcode === OpcodeJALR) || (opcode === OpcodeBRANCH)
})
val instIsJal = VecInit((0 until NumInsts).map { i =>
  io.fetchData.bits.inst(i)(6, 0) === OpcodeJAL
})

// Find the index of the first branch (NumInsts means "no branch")
val firstBranchIdx = Wire(UInt(4.W))
firstBranchIdx := NumInsts.U
for (i <- (NumInsts - 1) to 0 by -1) {
  when(instIsBranch(i)) {
    firstBranchIdx := i.U
  }
}

val branchInFetch = firstBranchIdx < NumInsts.U
val nValidInst    = Mux(branchInFetch, firstBranchIdx + 1.U, NumInsts.U)

// Compute next PC after a branch in the fetch line
// For JAL: target = instPC + sign_extended(jalImm)
// For others: target = instPC + 4 (next sequential instruction)
val branchInstPC = io.fetchData.bits.addr + (firstBranchIdx << 2)(31, 0)

val branchInst = io.fetchData.bits.inst(firstBranchIdx(2, 0))  // safe: only used when branchInFetch
val jalImm = Wire(SInt(21.W))
jalImm := Cat(
  branchInst(31),        // imm[20]
