// Priority: source 0 (fetch) has highest priority
val anyFault = io.faults.map(_.valid).reduce(_ || _)

// Find the first valid fault source using priority encoder
val firstFaultIdx = Wire(UInt(log2Ceil(NumSources + 1).W))
firstFaultIdx := NumSources.U
for (i <- (NumSources - 1) to 0 by -1) {
  when(io.faults(i).valid) {
    firstFaultIdx := i.U
  }
}

// Selected fault signals (Mux-selected from first valid source)
val selCause = Wire(UInt(32.W))
val selTval  = Wire(UInt(32.W))
val selPC    = Wire(UInt(32.W))
selCause := 0.U; selTval := 0.U; selPC := 0.U
for (i <- 0 until NumSources) {
  when(firstFaultIdx === i.U) {
    selCause := io.faults(i).cause
    selTval  := io.faults(i).tval
    selPC    := io.faults(i).pc
  }
}

// Latch the first detected fault
val faultLatched = RegInit(false.B)
val faultCause   = Reg(UInt(32.W))
val faultTval    = Reg(UInt(32.W))
val faultPC      = Reg(UInt(32.W))

when(!faultLatched && anyFault) {
  faultLatched := true.B
  faultCause   := selCause
  faultTval    := selTval
  faultPC      := selPC
}

io.fault       := faultLatched
io.trap.valid  := anyFault && !faultLatched
io.trap.target := io.mtvec
io.trap.mepc   := Mux(anyFault, selPC, faultPC)
io.trap.cause  := Mux(anyFault, selCause, faultCause)
io.trap.tval   := Mux(anyFault, selTval, faultTval)

